// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner, address notOwner) public {
        vm.assume(notOwner != c.owner());
        vm.prank(notOwner);
        bool ok = true;
        try c.transferOwnership(newOwner) {} catch {
            ok = false;
        }
        assertTrue(ok == false);
    }
}
